import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"HoloCine: Holistic Generation of Cinematic Multi-Shot Long Video Narratives","description":"","frontmatter":{"title":"HoloCine: Holistic Generation of Cinematic Multi-Shot Long Video Narratives","arxiv":"2510.20822","date":"2025-10-23","authors":"Yihao Meng, Hao Ouyang, Yue Yu, Qiuyu Wang, Wen Wang, Ka Leong Cheng, Hanlin Wang, Yixuan Li, Cheng Chen, Yanhong Zeng, Yujun Shen, Huamin Qu","categories":"cs.CV","topics":"智能体视频生成, 多镜头长视频, 稀疏注意力","outline":[2,2]},"headers":[],"relativePath":"papers/2510.20822.md","filePath":"papers/2510.20822.md","lastUpdated":null}'),e={name:"papers/2510.20822.md"};function l(i,s,r,m,c,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="holocine-holistic-generation-of-cinematic-multi-shot-long-video-narratives" tabindex="-1">HoloCine: Holistic Generation of Cinematic Multi-Shot Long Video Narratives <a class="header-anchor" href="#holocine-holistic-generation-of-cinematic-multi-shot-long-video-narratives" aria-label="Permalink to &quot;HoloCine: Holistic Generation of Cinematic Multi-Shot Long Video Narratives&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2510.20822" target="_blank" rel="noreferrer">2510.20822</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-10-23</td></tr><tr><td><strong>作者</strong></td><td>Yihao Meng, Hao Ouyang, Yue Yu, Qiuyu Wang, Wen Wang, Ka Leong Cheng, Hanlin Wang, Yixuan Li, Cheng Chen, Yanhong Zeng, Yujun Shen, Huamin Qu</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把整段多镜头叙事放进一次去噪里整体生成：window cross-attention 把每个镜头钉死在自己的 prompt 上，sparse inter-shot self-attention 把跨镜头信息压缩成每镜头首帧的摘要 token，从而在单次前向内同时拿到镜头切分与跨镜头一致性。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/agentic">智能体视频生成</a></p></blockquote><p>本页依据 <code>arxiv.org/html/2510.20822v1</code> 全文撰写。</p><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>一分钟的叙事视频和&quot;更长的单镜头视频&quot;是两个问题。观众默认接受的电影语言由切换构成：远景交代环境，切近景给表情，再切回来。文本到视频模型这一侧的默认设定却是单镜头连续运动，多镜头被推给外部流水线处理——先分镜、逐镜头生成、最后剪辑拼接。这条路线里每个镜头都在各自独立的去噪轨迹上采样，角色的脸、服装、房间陈设之间没有任何机制强制它们相同，一致性只能靠事后注入参考图或训练角色 LoRA 来补。</p><p>HoloCine 问的是：能不能把整段多镜头叙事当作<strong>一个</strong>去噪对象一次生成完。这个提法把&quot;跨镜头一致性&quot;从后处理问题变回模型内部的表示问题。如果模型在同一段 latent 里同时持有全部镜头的全部帧，它就有条件自己维护一份跨镜头的实体状态，而不需要外部再把角色贴回去。代价同样明显：整段序列的 self-attention 是全长平方复杂度，60 秒多镜头视频直接把显存和时间吃穿。本文的两个模块正是冲着&quot;钉住语义&quot;和&quot;压掉复杂度&quot;这两件事去的。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>单镜头长视频生成</strong>这条线（自回归外推、滑窗续写等）能把时长做上去，但它生成的是一个不间断的连续镜头，没有剪辑点，也就没有电影语言。想要切镜必须在外面剪，一旦剪就回到了拼接问题。</p><p><strong>两阶段分镜流水线</strong>是当前多镜头的主流：LLM 写分镜脚本，逐个镜头调 T2V/I2V，再拼起来。它可控、可解释、能复用现成模型，弱点在跨镜头一致性完全依赖外挂机制（参考图、ID LoRA、首尾帧续接），而这些机制对&quot;同一个人换角度、换景别&quot;这种情况并不稳。本文的表 1 里把这类两阶段方法的 SCA 一栏直接标成 <code>-</code>，因为它们的镜头边界是人为剪出来的，指标不适用。</p><p><strong>端到端多镜头方法</strong>（表 1 中的 CineTrans 与直接用 Wan2.2 生成的基线）已经在尝试让模型自己产生切换，但作者报告的 SCA 分别只有 0.5370 与 0.4843，意味着模型经常不按 prompt 规定的镜头数切，或者该切的地方不切。这个数字是本文立论的起点：多镜头能力当时并不是&quot;差一点&quot;，而是基本没有被可靠地控制住。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>先接受一个观察：现有 DiT 视频模型的 cross-attention 是全局的，一段文本对所有帧一视同仁。如果把 N 条镜头描述拼成一个长 prompt 喂进去，第 3 个镜头的帧同样会看到第 1 条描述，语义就会互相污染，模型自然分不清什么时候该切。要修这件事，最直接的想法是限制每一帧能看到哪一段文本——这不需要新模块，只需要在 cross-attention 上加掩码。</p><p>第二个观察是复杂度。整段生成的瓶颈在 self-attention，而多镜头视频的信息结构其实是稀疏的：同一镜头内部帧间高度相关，跨镜头之间真正需要传递的只有&quot;这个人长什么样、这个屋子什么样&quot;这类身份信息，不需要逐帧对齐。于是问题变成：跨镜头到底需要多少 token 才够。取每个镜头的首帧做摘要是最省的可行猜测，因为首帧通常已经把该镜头的主体和场景交代完了。</p><p>第三个观察是数据。要让模型学会&quot;在这里切&quot;，训练数据必须自带镜头边界标注。已有的自动切镜工具（TransNet V2 一类）加上多模态模型批量写分层 caption，正好能把这条数据管线跑起来。三个观察合起来，方法的形状就定了。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>多镜头生成失败的原因不是模型不会切镜头，是它不知道<strong>当前这一帧该听哪句话</strong>。把 cross-attention 限制成&quot;第 i 段帧只看全局 prompt 加第 i 条镜头 prompt&quot;，切换就成了模型可以推断的结构信号。而跨镜头之间真正要共享的只有身份级信息，用每个镜头首帧的摘要 token 当全局 KV 就够，稠密的全序列注意力是浪费。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>输入</strong>：一条全局 prompt（人物设定、整体场景、风格）加 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 条镜头级 prompt。全文的测试提示由 Gemini 2.5 Pro 生成，共 100 条这样的分层 prompt。</p><p><strong>Window Cross-Attention</strong>：第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 个镜头的 query <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">Q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 只与 <code>[全局 prompt, 第 i 条 prompt]</code> 做 cross-attention，其它镜头的文本被掩掉。镜头长度由 prompt 结构给定，因此掩码在采样前就完全确定。</p><p><strong>Sparse Inter-Shot Self-Attention</strong>：镜头内部保持稠密 self-attention；跨镜头的通路只保留每个镜头首帧的摘要 token，把它们拼成一份共享的全局 KV 供所有帧读取。</p><p><strong>数据</strong>：约 40 万条多镜头样本，单条最多 13 个镜头，分辨率 480×832，时长分 5 秒、15 秒、60 秒三档。切镜用 TransNet V2，分层 caption 用 Gemini 2.5 Flash 生成，并在镜头交界处插入 <code>[shot cut]</code> 标记。</p><p><strong>训练</strong>：基座 Wan2.2 14B（消融实验用 5B 版本），10k 步，学习率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">5</span></span></span></span></span></span></span></span></span></span></span></span>，128 张 H800，FSDP 加 Context Parallelism，注意力用 FlashAttention-3 的 varlen 接口以适配不等长镜头。</p><p><strong>一个具体例子</strong>：全局 prompt 写明&quot;戴红围巾的女人，冬夜的旧书店&quot;，镜头 1 写&quot;推门进店的远景&quot;，镜头 2 写&quot;她低头翻书的特写&quot;，镜头 3 写&quot;店主从柜台后抬头&quot;。生成时第 2 段帧的 cross-attention 只能看到全局 prompt 与&quot;低头翻书的特写&quot;，所以不会把&quot;推门&quot;动作混进来；同时它通过全局 KV 读到镜头 1 首帧的摘要 token，红围巾与书店的陈设因此得以延续。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>整段生成的朴素 self-attention 复杂度是全序列平方。记镜头数为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、单镜头 latent token 数为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span></span></span></span>、每镜头摘要 token 数为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span></span></span></span>，则</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2141em;vertical-align:-0.35em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord mathnormal">L</span><span class="mclose"><span class="mclose">)</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">⟶</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2141em;vertical-align:-0.35em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord mathnormal">L</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mclose">)</span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mord">.</span></span></span></span></span></p><p>左边随镜头数二次增长且系数是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span>；右边把二次项挪到了 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0611em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-2.453em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span></span></span></span> 上，而 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≪</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span></span></span></span>，因此在镜头数增加时增长要缓和得多。这是本文能把 60 秒档做进训练的直接原因。</p><p>镜头结构服从度用 Shot Cut Accuracy 衡量：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathrm">SCA</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">exp</span><span class="mopen">(</span><span class="mord">−</span><span class="mord"><span class="mord mathrm">NSD</span></span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathrm">NSD</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.1963em;vertical-align:-0.836em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">total</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">matched</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">penalty</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.836em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mord">.</span></span></span></span></span></p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathrm">NSD</span></span></span></span></span> 把&quot;检测到的切点与规定切点的错位量&quot;和&quot;多切/漏切的惩罚项&quot;一起除以总帧数做归一化，再取负指数压到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>。这个设计使得完全对齐时 SCA 趋近 1，错位越大衰减越快。它度量的是<strong>剪辑点的位置正确性</strong>，与画面内容质量无关，这一点在 §9 与 §11 会成为主要攻击面。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>第一个问题是模型到底听不听镜头指令。表 1 首列 SCA：HoloCine 0.9837，CineTrans 0.5370，直接用 Wan2.2 生成 0.4843；两阶段方法因为切点是外部剪出来的而标为 <code>-</code>。按这个指标，端到端路线此前确实没把镜头结构学会，而整体式生成加窗口掩码把它推到了接近饱和。</p><p>第二个问题是两个模块各自贡献多少。表 2 在 5B 基座上做消融，SCA 一列：去掉 window cross-attention 掉到 0.6266，改用完整稠密注意力 0.8923，稀疏注意力配零初始化 0.9675，完整稀疏方案 0.9736。窗口掩码是镜头结构的决定性因素，这一点很干净。需要说清楚的是后三档之间的差距（0.8923 → 0.9736）只说明稀疏化没有损伤切镜能力，它<strong>不能</strong>用来证明稀疏化保住了跨镜头一致性，因为 SCA 根本不测一致性。</p><p>第三个问题是整体式生成有没有带来预期之外的性质。作者报告了两点定性结论：一是涌现的跨镜头记忆，同一角色与场景在多个镜头间自发保持；二是镜头语言可控，通过 prompt 可以指定景别与运镜。这两条以定性展示为主。作者同时给出了失败案例：把水倒进杯子之后，后续镜头里杯子又变回空的，说明模型维持的是视觉外观级的一致性，物体状态的因果链条没有被建模。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句版</strong>：多镜头叙事的困难在于每一帧该听哪句话，而不在于时长。Window cross-attention 用一个纯掩码把镜头与 prompt 绑定，把切镜从生成难题变成结构约束。跨镜头只需传递身份级信息，用首帧摘要 token 做全局 KV 就能把复杂度里的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span> 项从镜头数的平方上剥掉。整体式生成会自发涌现跨镜头记忆，但这种记忆停留在外观层，不覆盖物体状态的因果演化。SCA 这类结构指标接近饱和之后，评测的重心必须转移到一致性与叙事合理性上。</p><p><strong>3 句版</strong>：把整段多镜头视频当成一个去噪对象，用窗口化 cross-attention 钉住语义、用稀疏跨镜头注意力控住算力。SCA 从 0.48/0.54 提到 0.9837，消融显示窗口掩码是主因。涌现的一致性是外观级的，倒水后杯子变空这类失败暴露出因果建模的缺口。</p><p><strong>1 句版</strong>：多镜头长视频可以一次性整体生成，前提是把&quot;哪一帧听哪句 prompt&quot;写成注意力掩码，并把跨镜头通路压缩到每镜头首帧。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最要命的一条是：<strong>每个镜头的首帧摘要 token 足以承载该镜头需要跨镜头传递的全部信息</strong>。稀疏跨镜头注意力把全局 KV 完全建立在首帧上，等于假设一个镜头的主体、服装、场景在首帧就已经出现且具有代表性。电影语言恰恰经常违反这一点：从空镜头摇到人物、人物中途入画、先拍手部特写再揭示是谁，这些情况下首帧不含主体，后续镜头就拿不到该角色的视觉证据。</p><p>论文为这条假设提供的证据是间接的。表 2 显示稀疏方案的 SCA（0.9736）不低于稠密方案（0.8923），但 SCA 度量的是剪辑点位置，对身份漂移完全不敏感，因此它无法充当&quot;稀疏化没有损失一致性&quot;的证据。一致性方面作者给的是定性展示与涌现记忆的描述，我在可见正文中没有找到针对&quot;首帧不含主体&quot;这一类构造的定量测试。这属于缺失证据，而非反证。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要复现 128 卡训练。用 5B 基座在小规模数据上做对照即可：</p><ol><li>取一个公开多镜头素材源，用 TransNet V2 切镜，保留 4–6 镜头、每镜头约 3 秒的样本约 2–5k 条，用任一多模态模型写分层 caption。</li><li>训两个变体：全局 cross-attention 与 window cross-attention，其余完全相同。</li><li>测两个量：一是 SCA（按 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">exp</span><span class="mopen">(</span><span class="mord">−</span><span class="mord"><span class="mord mathrm">NSD</span></span><span class="mclose">)</span></span></span></span> 实现，切点检测器与训练用的切镜工具须不同以避免自证）；二是自定的跨镜头身份相似度，做法是在每个镜头<strong>均匀采样 5 帧</strong>而非只取首帧，用人脸或实体检测裁出主体后算特征相似度。</li><li>判据：若 window 变体的 SCA 明显高于全局变体，则窗口掩码是切镜的主因这一结论成立；若两者的身份相似度差异不显著，则说明一致性来自基座与数据而非本文模块，这会削弱&quot;涌现记忆&quot;的归因。</li></ol><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最强的攻击针对 SCA 本身。构造一个<strong>平凡基线</strong>：用任意单镜头 T2V 模型按 prompt 逐镜头独立生成，然后在规定的时间戳硬剪拼接。这个基线的切点位置按构造与 prompt 完全一致，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">matched</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">penalty</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 都趋近 0，SCA 应当接近 1.0，也就是说它会与 HoloCine 的 0.9837 打平甚至更高，而它的跨镜头一致性为零。论文把两阶段方法的 SCA 标成 <code>-</code> 恰好意味着这个对照从未被量化——用来区分 HoloCine 与 Wan2.2 的头条数字（0.9837 对 0.4843），在最容易刷满它的那一族方法上没有被测过。这不构成对方法本身的否定，但它说明表 1 首列不能单独作为&quot;多镜头能力&quot;的证据。</p><p>第二重攻击针对首帧假设：构造一批 prompt，强制每个镜头以空镜或局部特写开场、主体在镜头中段才入画，在这批数据上对比稀疏与稠密注意力的身份一致性。若稀疏方案的退化显著大于稠密方案，则复杂度收益是以可预测的失败模式换来的，且这种模式在真实剪辑中很常见。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>驱动 idea 的局限是那个倒空的杯子：模型维持的是外观一致性，不是<strong>状态</strong>一致性。跨镜头共享的是像素级摘要，而叙事需要共享的是&quot;水已经倒进去了&quot;&quot;门已经开了&quot;&quot;这个人已经受伤了&quot;这类可被后续镜头继承的离散事实。</p><p>可借鉴的相邻工具来自程序合成与具身规划里的符号状态跟踪：把每个镜头的输出经一个抽取器映射成一组实体-属性断言，作为下一镜头的额外条件，并对断言的单调性施加约束（不可逆事件不得回退）。跨镜头 KV 因此从&quot;首帧视觉摘要&quot;升级为&quot;视觉摘要加状态断言&quot;，这也顺带修掉了 §9 里首帧不含主体的问题，因为断言不依赖某一特定帧。</p><p>第一个实验不需要重训基座：构造 200 条包含单一不可逆事件的两镜头 prompt（倒水、点燃、打碎、穿上），只在推理时把第一镜头抽取到的断言追加进第二镜头的文本条件，测量状态回退率。若回退率显著下降，就证明外观通路与状态通路应当分离；若不下降，则说明基座在预训练中根本没学到这些状态的视觉表征，问题要回到数据侧解决。</p>',52)])])}const d=a(e,[["render",l]]);export{g as __pageData,d as default};
